public class RecursiveRangeSum {
    static long sumRange(int[] values, int from, int to) {
        if (values == null) {
            throw new IllegalArgumentException("values cannot be null");
        }
        if (from < 0 || from > to || to > values.length) {
            throw new IndexOutOfBoundsException("require 0 <= from <= to <= length");
        }
        if (from == to) {
            return 0L;
        }
        return values[from] + sumRange(values, from + 1, to);
    }

    static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw error;
        }
        throw new AssertionError("expected " + type.getSimpleName());
    }

    public static void main(String[] args) {
        int[] values = {4, -2, 7, 1};
        assert sumRange(values, 0, 4) == 10;
        assert sumRange(values, 1, 3) == 5;
        assert sumRange(values, 2, 2) == 0;
        assert sumRange(new int[0], 0, 0) == 0;
        assert sumRange(new int[] {-5}, 0, 1) == -5;
        expect(IllegalArgumentException.class, () -> sumRange(null, 0, 0));
        expect(IndexOutOfBoundsException.class, () -> sumRange(values, -1, 2));
        expect(IndexOutOfBoundsException.class, () -> sumRange(values, 3, 2));
        expect(IndexOutOfBoundsException.class, () -> sumRange(values, 0, 5));
        System.out.println("recursive-range-sum checks: OK");
    }
}

